.fx-vcp .vid{position:relative;overflow:hidden;background:linear-gradient(115deg,color-mix(in srgb,var(--primary) 60%,#000),color-mix(in srgb,var(--primary) 78%,#000),color-mix(in srgb,var(--accent) 45%,color-mix(in srgb,var(--primary) 60%,#000)),color-mix(in srgb,var(--accent) 80%,#000),color-mix(in srgb,var(--primary) 60%,#000));background-size:300% 300%;animation:fxvidbg-vcp calc(14s/var(--speed)) ease-in-out infinite}
.fx-vcp .vid::before{content:"";position:absolute;width:55%;aspect-ratio:1;border-radius:50%;right:-10%;top:-30%;background:radial-gradient(circle,rgba(255,255,255,.35),transparent 65%);animation:fxvidfloat-vcp calc(9s/var(--speed)) ease-in-out infinite alternate}
.fx-vcp .vid::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 45%,rgba(0,0,0,.35));pointer-events:none}
@keyframes fxvidbg-vcp{50%{background-position:100% 100%}}
@keyframes fxvidfloat-vcp{to{transform:translate(-40%,30%) scale(1.2)}}
@media(prefers-reduced-motion:reduce){.fx-vcp .vid,.fx-vcp .vid::before{animation:none}}
.fx-vcp{width:min(980px,100%);display:grid;gap:1.4em}
.fx-vcp h2{font-size:clamp(1.6em,3.6vw,2.2em)}
.fx-vcp .gr{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.3em}
.fx-vcp .th{position:relative;display:block;width:100%;aspect-ratio:16/10;padding:0;border:0;border-radius:var(--radius);overflow:hidden;cursor:pointer;color:#fff}
.fx-vcp .th .vid{position:absolute;inset:0;animation-play-state:paused}.fx-vcp .th .vid.a2{filter:hue-rotate(40deg)}.fx-vcp .th .vid.a3{filter:hue-rotate(-40deg) saturate(.9)}
.fx-vcp .th.on .vid,.fx-vcp .th.on .vid::before,.fx-vcp .th:hover .vid,.fx-vcp .th:hover .vid::before{animation-play-state:running}
.fx-vcp .th:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-vcp .pb{position:absolute;left:50%;top:50%;z-index:2;width:3.2em;height:3.2em;margin:-1.6em 0 0 -1.6em;border-radius:50%;background:rgba(255,255,255,.94);color:color-mix(in srgb,var(--primary) 65%,#000);display:grid;place-items:center;opacity:0;transform:scale(.8);transition:all calc(.3s/var(--speed)) cubic-bezier(.3,1.5,.5,1)}
.fx-vcp .pb svg{width:1.2em;height:1.2em;margin-left:.1em}.fx-vcp .th:hover .pb,.fx-vcp .th:focus-visible .pb{opacity:1;transform:none}
.fx-vcp .th.on .pb svg{margin:0}
.fx-vcp .du{position:absolute;right:.6em;bottom:.9em;z-index:2;padding:.2em .5em;border-radius:5px;background:rgba(0,0,0,.65);font:700 .72em var(--font-body);font-variant-numeric:tabular-nums}
.fx-vcp .eq{position:absolute;left:.7em;top:.7em;z-index:2;display:none;align-items:flex-end;gap:2px;height:1.1em;padding:.3em .5em;border-radius:6px;background:rgba(0,0,0,.55);box-sizing:content-box}
.fx-vcp .th.on .eq{display:flex}.fx-vcp .eq i{width:3px;height:100%;background:#fff;border-radius:2px;transform-origin:bottom;animation:fxvcpeq calc(.9s/var(--speed)) ease-in-out infinite alternate}.fx-vcp .eq i:nth-child(2){animation-delay:-.3s}.fx-vcp .eq i:nth-child(3){animation-delay:-.6s}
@keyframes fxvcpeq{from{transform:scaleY(.2)}to{transform:scaleY(1)}}
.fx-vcp .bar{position:absolute;left:0;right:0;bottom:0;height:.28em;z-index:2;background:rgba(255,255,255,.3)}.fx-vcp .bar i{display:block;height:100%;width:var(--w);background:var(--accent)}
.fx-vcp .mt{padding:.8em .1em 0}.fx-vcp .mt b{display:block;font:600 1.05em var(--font-heading)}.fx-vcp .mt small{opacity:.6;font-size:.82em}
@media(max-width:760px){.fx-vcp .gr{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.fx-vcp .pb{transition:none}.fx-vcp .eq i{animation:none;transform:scaleY(.6)}}

/* touch: :hover mirrored as .is-tap */
.fx-vcp .th.is-tap .vid{animation-play-state:running}
.fx-vcp .th.is-tap .vid::before{animation-play-state:running}
.fx-vcp .th.is-tap .pb{opacity:1;transform:none}

