(function(){var root=document.querySelector('.fx-vcp'),PL='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5v13a1 1 0 0 0 1.5.86l11-6.5a1 1 0 0 0 0-1.72l-11-6.5A1 1 0 0 0 8 5.5z" fill="currentColor"/></svg>',PA='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="6" y="5" width="4" height="14" rx="1" fill="currentColor"/><rect x="14" y="5" width="4" height="14" rx="1" fill="currentColor"/></svg>',iv=null,cur=null;
function stop(){clearInterval(iv);if(cur){cur.classList.remove('on');cur.setAttribute('aria-pressed','false');cur.querySelector('.pb').innerHTML=PL;cur=null}}
root.querySelectorAll('.th').forEach(function(b){b.addEventListener('click',function(){if(cur===b){stop();return}stop();cur=b;b.classList.add('on');b.setAttribute('aria-pressed','true');b.querySelector('.pb').innerHTML=PA;var bar=b.querySelector('.bar'),w=parseFloat(bar.style.getPropertyValue('--w'))||0;
iv=setInterval(function(){w=Math.min(100,w+.5);bar.style.setProperty('--w',w+'%');if(w>=100){stop()}},100)})})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
